package com.sigo.asistencia.asistencia.controller; import com.sigo.asistencia.asistencia.dto.*; import com.sigo.asistencia.relevo.dto.*; import com.sigo.asistencia.asistencia.service.DashboardAsistenciaService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/dashboard/asistencia") @RequiredArgsConstructor public class DashboardAsistenciaController{private final DashboardAsistenciaService s;@GetMapping("/diario") public List<DashboardPuntoResponse> diario(@RequestParam int anio,@RequestParam int mes){return s.diario(anio,mes);}@GetMapping("/anual") public List<DashboardPuntoResponse> anual(@RequestParam int anio){return s.anual(anio);}@GetMapping("/ausencias-motivo") public List<AusenciaMotivoResponse> motivos(@RequestParam int anio,@RequestParam(required=false)Integer mes){return s.motivos(anio,mes);}@GetMapping("/resumen") public ResumenAsistenciaResponse resumen(@RequestParam(required=false)LocalDate inicio,@RequestParam(required=false)LocalDate fin){return s.resumen(inicio,fin);}}
